with valid as (select *, last_day(last_restock) as last_restock_month_end, date_trunc('year', last_restock) as last_restock_period from inventory where last_restock < '2023-06-01') select *, avg(quantity) over (partition by store_id, product_id order by last_restock_period, id rows between 2 preceding and 1 preceding) as quantity_avg_2_prior, count(quantity) over (partition by store_id, product_id) as store_id_count_quantity, dense_rank() over (partition by store_id order by quantity desc nulls last) as quantity_dense_rank from valid
